(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.ToadalSupportContact=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
function enhance(doc,config,fetchImpl){const form=doc?.querySelector?.('form.gated-form[aria-describedby="contact-form-status"]');if(!form||!config?.features?.support||!config.supportEndpoint)return{enhanced:false};fetchImpl=fetchImpl||globalThis.fetch;const controls=[...form.querySelectorAll('input,select,textarea,button[type="submit"]')];controls.forEach(c=>c.disabled=false);const status=doc.getElementById('contact-form-status')||(()=>{const p=doc.createElement('p');p.id='contact-form-status';p.setAttribute('role','status');p.setAttribute('aria-live','polite');form.append(p);return p;})();form.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form);const payload={category:String(fd.get('category')||''),email:String(fd.get('email')||''),subject:String(fd.get('subject')||''),message:String(fd.get('message')||'')};if(fd.get('attachment')){status.textContent='Attachments are not sent by this integration until an approved upload contract exists.';return;}status.textContent='Sending…';try{const r=await fetchImpl(config.supportEndpoint,{method:'POST',headers:{'content-type':'application/json','accept':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw new Error('HTTP '+r.status);status.textContent='Message sent successfully.';form.reset();}catch(err){status.textContent='Message was not sent. Please retry later; no success was recorded.';}});return{enhanced:true};}
return{enhance};});
